import Anthropic from "@anthropic-ai/sdk";

const client = new Anthropic();

const SYSTEM = `You are a fintech assistant.
You MUST always call verify_customer_identity before calling initiate_wire_transfer.
This is a regulatory requirement. Never skip verification.`;

// FIX: track verification state in the harness, not in the model's memory
let identityVerified = false;

async function executeTool(
  toolName: string,
  toolInput: Record<string, unknown>
): Promise<string> {
  if (toolName === "verify_customer_identity") {
    const result = await verifyIdentity(toolInput.customerId as string);
    identityVerified = true; // record that verification completed
    return result;
  }

  if (toolName === "initiate_wire_transfer") {
    // Programmatic gate: enforce prerequisite regardless of model behaviour
    if (!identityVerified) {
      return JSON.stringify({
        error: "PREREQUISITE_NOT_MET",
        message: "Identity verification must be completed before initiating a transfer. Please call verify_customer_identity first."
      });
    }
    return await initiateTransfer(toolInput);
  }

  throw new Error(`Unknown tool: ${toolName}`);
}
